SELECT jsonb_build_object('events',(SELECT jsonb_agg(to_jsonb(e)||jsonb_build_object('row_hash',md5(to_jsonb(e)::text)) ORDER BY id_evento) FROM tb_evento_corridas e WHERE id_evento IN (43657,39395,37774,38982,37572,47147)),'routes',(SELECT jsonb_agg(to_jsonb(p)||jsonb_build_object('row_hash',md5(to_jsonb(p)::text)) ORDER BY id_evento_percurso) FROM tb_evento_corridas_percursos p WHERE id_evento IN (43657,39395,37774,38982,37572,47147)),'functions',(SELECT jsonb_agg(pg_get_functiondef(oid)) FROM pg_proc WHERE proname IN ('grava_evento_corridas_percursos','registra_evento_fatos_historico')),'auditColumns',(SELECT jsonb_agg(to_jsonb(c)) FROM (SELECT table_name,column_name,data_type FROM information_schema.columns WHERE table_name ILIKE '%fatos%' AND table_schema='public') c),'memberships',(SELECT jsonb_agg(to_jsonb(g)) FROM tb_agregadores_eventos g WHERE id_evento IN (43657,39395,37774,38982,37572,47147)))::text payload
